mapper.select:
select distinct c1.C_Name as cName, c1.C_Code as cCode, c1.C_Creditcode as cCreditcode, mn.c_id as cId, mn.c_type as cType, mn.Pu_Order as puOrder from SYS_Participant_Unit mn left join Pre_Project pro on pro.P_Id=mn.P_Id left join Sys_Company c1 on c1.C_Id=mn.C_Id where 1=1
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Pu_Order ASC

select pro.P_Name as pName, pro.P_Name_History as pNameHistory, c1.C_Name as cName, c1.C_Code as cCode, c1.C_Name_History as cNameHistory, c1.C_Creditcode as cCreditcode, mn.* from SYS_Participant_Unit mn left join Pre_Project pro on pro.P_Id=mn.P_Id left join Sys_Company c1 on c1.C_Id=mn.C_Id where 1=1
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Pu_Order ASC
limit #{params.start},#{params.size}
